import MenuJson from "./menus.json";

export default {
  name: "Navbar",
  data() {
    return {
      menu: MenuJson,
      isLanguage: true,
    };
  },
  created() {},
  methods: {
    clearHistory() {
      this.$router.replace(`/shop`); 
    }
  },
  mounted() {
    console.log(this.$route.path)
    // Replace the current route with a new route (for example, '/home' or '/anotherPage')
    if (this.$route.path === '/product/detail') {
      this.$router.replace('/anotherPage');  // This will replace the URL in the history stack
    }
  }
};
